class Solution:
    def evaluateTree(self, root) -> bool:
        if not root.left and not root.right:
            return bool(root.val)
        left_val = self.evaluateTree(root.left)
        right_val = self.evaluateTree(root.right)
        if root.val == 2:
            return left_val or right_val
        return left_val and right_val

class Solution {
public:
    bool evaluateTree(TreeNode* root) {
        if (!root->left && !root->right) return root->val == 1;
        bool leftVal = evaluateTree(root->left);
        bool rightVal = evaluateTree(root->right);
        return root->val == 2 ? (leftVal || rightVal) : (leftVal && rightVal);
    }
};

class Solution {
    public boolean evaluateTree(TreeNode root) {
        if (root.left == null && root.right == null) return root.val == 1;
        boolean leftVal = evaluateTree(root.left);
        boolean rightVal = evaluateTree(root.right);
        return root.val == 2 ? (leftVal || rightVal) : (leftVal && rightVal);
    }
}

var evaluateTree = function(root) {
    if (!root.left && !root.right) return root.val === 1;
    const leftVal = evaluateTree(root.left);
    const rightVal = evaluateTree(root.right);
    return root.val === 2 ? (leftVal || rightVal) : (leftVal && rightVal);
};
